
/* ================= CLIENT PORTAL ================= */
const PT={approved:false,notes:[['n1','My morning routine ideas','Wake 6:00, 20 min walk, protein breakfast…','#FF8A6B','Today'],['n2','Questions for the next call','1. Can the quiz have photos? 2. When do emails start?','#7A5CF2','Yesterday'],['n3','Client wins to share','Sarah lost 6kg and kept it off.','#13A592','3 days ago']]};
const PNAVP=[['home','Home','home'],['requests','Requests','inbox',2],['files','Files','folder'],['messages','Messages','msg'],['notes','My notes','note']];
function pFrame(cur,body){return `<div class="p-ribbon">${ic('lock',16)}<span>Preview of what Harry will see. Clients can’t sign in until the security tests pass.</span></div>
<header class="pnav"><div class="p-brand"><span class="cmono">HK</span><div class="hide-m"><b>Harry Kaye PT</b><small>with Layer2Funnels</small></div></div><nav class="links" aria-label="Portal">${PNAVP.map(([k,l,i,b])=>`<button data-act="nav:portal/${k}" ${cur===k?'aria-current="page"':''}>${ic(i,18)}<span>${l}</span>${b?`<span class="bd">${b}</span>`:''}</button>`).join('')}</nav><button class="btn ghost sm" data-act="nav:launcher" aria-label="Exit preview">${ic('x',16)}<span class="hide-m">Exit preview</span></button></header><div class="portal">${body}</div>`}
const MIL=[['Signed','28 Sep'],['Brand Base','2 Oct'],['Strategy','Now'],['Copy','Late Oct'],['Build','November'],['Marketing','December']];
VIEWS.portal=p=>{const pg=p[0]||'home';const now=PT.approved?3:2;
if(pg==='home'){const pct=Math.round(now/6*100);return pFrame('home',`<div class="p-hero"><p class="over">Your quiz funnel</p><h1>Hi Harry. ${PT.approved?'Strategy approved. On to copy!':'One thing needs you this week.'}</h1><p>We update this page as work moves, so you never have to chase us.</p></div>
<section class="road" aria-label="Your journey"><svg class="path" viewBox="0 0 1000 90" preserveAspectRatio="none" aria-hidden="true"><defs><linearGradient id="roadg" x1="0" x2="1"><stop offset="0" stop-color="#FF7A45"/><stop offset=".6" stop-color="#FFB547"/><stop offset="1" stop-color="#7A5CF2"/></linearGradient></defs><path class="pbg" d="M40 30 C 180 30, 180 70, 300 70 S 420 30, 500 30 S 640 70, 700 70 S 840 30, 960 30"/><path class="pfg" style="--p:${(now/5).toFixed(2)}" d="M40 30 C 180 30, 180 70, 300 70 S 420 30, 500 30 S 640 70, 700 70 S 840 30, 960 30"/><path class="pdash" d="M40 30 C 180 30, 180 70, 300 70 S 420 30, 500 30 S 640 70, 700 70 S 840 30, 960 30"/></svg>
<div class="miles" role="list">${MIL.map(([n,d],i)=>`<div class="mile ${i<now?'done':i===now?'now':''}" role="listitem"><span class="pin">${i<now?ic('check',24,'',2.8):i+1}</span><b>${n}</b><small>${i<now?'Done':d}</small>${i===now?'<span class="you">You are here</span>':''}</div>`).join('')}</div>
<div class="rocket"><span class="rk" aria-hidden="true">🚀</span><div style="flex:1"><b>${pct}% of the way to launch</b><div class="meter" style="--v:${pct}%;margin-top:8px"><i></i></div></div><small style="opacity:.8" class="hide-m">Launch: late November</small></div></section>
<div class="next" id="nextstep" style="margin-top:22px">${PT.approved?`<svg class="drawn" viewBox="0 0 100 100" fill="none" stroke-width="5" stroke-linecap="round"><circle cx="50" cy="50" r="45"/><path d="M32 52l12 12 25-27"/></svg><div><p class="over">Done</p><h2>Thanks, Harry. Strategy approved.</h2><p>Sana starts your quiz copy on Monday. You’ll see the first draft here next week.</p></div>`:`<div class="doc-thumb" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><div><p class="over" style="color:var(--text)">Your next step · due Friday</p><h2>Approve your strategy (v2)</h2><p>Your avatar, offer and funnel plan in one place. About 10 minutes to read.</p><div class="acts"><button class="btn primary" data-act="papprove">${ic('check',18,'',2.4)}Approve strategy</button><button class="btn ghost" data-act="nav:portal/requests">Ask for changes</button><button class="btn quiet" data-act="toast:Opens version 2 exactly as the team shared it.">${ic('eye',18)}Open v2</button></div></div>`}</div>
<div class="p-grid"><section class="panel"><div class="sec-h"><h2>Your wins so far</h2></div><div class="badges" style="padding:0 20px 20px">${[['🎉','Kick-off','#FFD27A','#FF9A3D','#C46A12',1],['🎨','Brand Base','#FFB2C8','#E9488F','#A82462',1],['🧭','Strategy','#C3B0FF','#7A5CF2','#5030C0',PT.approved],['✍️','Copy','#9FE6D8','#13A592','#0A7064',0],['🚀','Launch','#A9C4FF','#2B63F6','#1A3BAE',0]].map(([e,l,a,b,c,on])=>`<span class="bdg ${on?'':'lock'}" style="--c1:${a};--c2:${b};--c3:${c}"><i>${e}</i>${l}</span>`).join('')}</div></section>
<section class="panel"><div class="sec-h"><h2>Waiting on you</h2><span class="n">2</span></div><div class="rows">${[['upload','Upload your logo files','PNG or SVG'],['forms','3 quick questions about pricing','About 4 minutes']].map(([i,t,s])=>`<button class="linkrow" data-act="nav:portal/requests">${`<span class="tic ap">${ic(i,18)}</span>`}<span class="main"><b>${t}</b><small>${s}</small></span>${ic('right',16)}</button>`).join('')}</div></section>
<section class="panel"><div class="sec-h"><h2>Updates from your team</h2></div><ul class="timeline">${[['TR','Strategy v2 is ready. We tightened the offer.','Today, 11:20'],['UM','Your avatar is done: busy mums getting back to fitness.','Monday'],['TR','Brand Base complete. Thanks for the answers!','2 Oct']].map(([a,t,w])=>`<li>${av(a)}<div><p>${t}</p><small>${w}</small></div></li>`).join('')}</ul></section>
<section class="panel"><div class="sec-h"><h2>Your team</h2></div><div class="team">${av('TR',52)}<div style="flex:1"><b>Tabish Riaz</b><p class="hint">Account lead · replies within a working day</p></div><button class="btn ghost sm" data-act="hi5">${ic('heart',18)}High five</button></div></section></div>`)}
if(pg==='requests')return pFrame('requests',`${head('Requests','Things your team needs from you. Reply right here.')}<div style="display:grid;gap:14px">${[['Approve your strategy (v2)','Approval','Due Friday','Strategy',1],['Upload your logo files','Information','Due Friday','Strategy',0],['3 quick questions about pricing','Information','Next week','Strategy',0]].map(([t,ty,d,s,ap],i)=>`<section class="panel" style="padding:20px"><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><span class="pill ${ap?'brand':''}">${ty}</span><span class="pill warn">${d}</span><small class="muted">${s}</small></div><h2 class="h2" style="margin:10px 0 6px">${t}</h2><p class="tx2">${ap?'Version 2, shared by Tabish on 22 Oct. Approve it or tell us what to change.':'Drop files here or answer below. We’ll get a notification.'}</p>${ap?`<div class="ver" style="margin:12px 0"><span class="ft pdf">PDF</span><span style="flex:1">Strategy v2.pdf</span><span class="pill">v2</span></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn primary" data-act="papprove">${ic('check',18,'',2.4)}Approve v2</button><button class="btn ghost" data-act="pchg">Request changes</button></div>`:`<div class="drop" style="margin:12px 0">${ic('clip',22)}<span>Drop files here, or <button class="linkbtn" data-act="toast:Preview only. Nothing is uploaded.">choose files</button></span></div><div class="compose"><textarea placeholder="Write your answer" aria-label="Answer"></textarea><button class="btn ink" data-act="toast:Preview only. Nothing was sent.">${ic('send',18)}</button></div>`}</section>`).join('')}</div>`);
if(pg==='files')return pFrame('files',`${head('Files','Everything your team has shared with you. Always the exact version.')}<div class="tblwrap"><table class="tbl"><thead><tr><th>File</th><th>Version</th><th>Shared</th><th></th></tr></thead><tbody>${[['Strategy v2.pdf','v2','Today','pdf'],['Customer avatar.pdf','v2','Monday','pdf'],['Brand Base summary.pdf','v1','2 Oct','pdf'],['Kick-off call notes.docx','v1','28 Sep','doc']].map(([n,v,d,t])=>`<tr><td class="t1"><span class="fname"><span class="ft ${t}">${t.toUpperCase()}</span>${n}</span></td><td data-l="Version">${v}</td><td data-l="Shared">${d}</td><td data-l=""><button class="btn ghost sm" data-act="toast:Preview only.">${ic('download',16)}Download</button></td></tr>`).join('')}</tbody></table></div>`);
if(pg==='messages')return pFrame('messages',`${head('Messages','Each conversation stays with its request.')}<div class="split"><section class="panel" style="padding:20px">${[['TR','Hi Harry! Strategy v2 is up. The big change is the offer: 12 weeks instead of 8.','11:20',0],['HK','Love it. Can we keep the free consult?','11:42',1],['TR','Yes, it’s the main call to action.','11:45',0]].map(([a,t,w,me])=>`<div class="comment" style="${me?'flex-direction:row-reverse;text-align:right':''}">${a==='HK'?'<span class="avatar" style="--av:#FF9A7E">HK</span>':av(a)}<div class="bub" style="${me?'background:var(--brand-soft);border-radius:14px 4px 14px 14px':''}">${t}<br><small>${w}</small></div></div>`).join('')}<div class="compose" style="margin-top:14px"><textarea placeholder="Write a message" aria-label="Message"></textarea><button class="btn ink" data-act="toast:Preview only. Nothing was sent.">${ic('send',18)}</button></div></section><section class="panel"><div class="sec-h"><h2>Conversations</h2></div><div class="rows">${['Strategy v2','Logo files','Pricing questions'].map((n,i)=>`<button class="linkrow" ${i?'':'style="background:var(--surface2)"'}>${ic('msg')}<span class="main"><b>${n}</b><small>${['3 messages','1 message','No messages yet'][i]}</small></span></button>`).join('')}</div></section></div>`);
if(pg==='notes')return pFrame('notes',`${head('My notes','Your own space for ideas, plans and practice. Only you can see these.',`<button class="btn primary" data-act="nav:portal/note/new">${ic('plus',18,'',2.2)}New note</button>`)}<div class="cardgrid">${PT.notes.map(([id,t,x,c,w])=>`<button class="pnote" data-act="nav:portal/note/${id}"><span class="hd" style="--c:${c}"></span><h3 class="h2" style="font-size:18px">${t}</h3><p class="tx2" style="font-size:14px">${x}</p><small class="muted">${ic('lock',12)} Private · ${w}</small></button>`).join('')}</div>`);
if(pg==='note'){const n=PT.notes.find(x=>x[0]===p[1])||['new','Untitled note','','#FF8A6B','Now'];return pFrame('notes',`<div class="toolbar"><button class="btn quiet sm" data-act="nav:portal/notes">${ic('right',16).replace('<svg','<svg style="transform:scaleX(-1)"')}My notes</button><span class="grow"></span><span class="pill">${ic('lock',12)} Only you</span><button class="btn ghost sm" data-act="toast:Shared with your team. They can read it, not edit.:ok">${ic('share',16)}Share with team</button><button class="btn primary sm" data-act="toast:Saved.:ok">Save</button></div><article class="docpage" style="min-height:60vh"><div contenteditable="true"><h1>${n[1]}</h1><p>${n[2]||'Start writing…'}</p></div></article>`)}
return pFrame('home','')};
Object.assign(ACT,{
papprove:()=>{PT.approved=true;confetti();toast('Preview only. Nothing was sent to the team.','ok');nav('portal/home',true)},
pchg:()=>dlg({title:'Request changes',body:`<div class="field" style="margin-top:12px"><label for="pc">What should change?</label><textarea id="pc" placeholder="Be as specific as you like"></textarea></div>`,acts:[['Cancel','noop'],['Send to team','toast:Preview only. Nothing was sent.','primary']]}),
hi5:(v,t)=>{if(!reduce){for(let i=0;i<8;i++){const h=document.createElement('span');h.textContent='❤';h.style.cssText=`position:fixed;z-index:120;pointer-events:none;color:#FF7A45;font-size:${16+Math.random()*14}px;left:${t.getBoundingClientRect().left+20+Math.random()*60}px;top:${t.getBoundingClientRect().top}px;transition:transform 1.2s cubic-bezier(.2,.8,.2,1),opacity 1.2s`;document.body.append(h);requestAnimationFrame(()=>{h.style.transform=`translate(${(Math.random()-.5)*80}px,-${120+Math.random()*80}px)`;h.style.opacity=0});setTimeout(()=>h.remove(),1300)}}toast('High five sent to Tabish! (Preview only)','ok')}
});
